-- ==============================================================================
-- GeoterRA - Catálogos Estáticos (Data Obligatoria)
-- ==============================================================================
-- Archivo:      GeoterRA_catalogs.sql
-- Descripción:  Contiene únicamente los INSERT INTO de la data estática
--               obligatoria para que el sistema funcione correctamente.
--               Incluye: Provincias, Cantones y Distritos de Costa Rica.
--
-- Uso:          Ejecutar DESPUÉS de importar GeoterRA_schema.sql
--               Flujo completo de reset:
--                 1. DROP DATABASE + CREATE DATABASE
--                 2. Importar GeoterRA_schema.sql  (estructura)
--                 3. Importar GeoterRA_catalogs.sql (este archivo)
--
-- Ejemplo:
--   mysql -u usuario -p GeoterRA < GeoterRA_schema.sql
--   mysql -u usuario -p GeoterRA < GeoterRA_catalogs.sql
-- ==============================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

